export function getMarketParams(market) {
  return {
    loanToken: market.loanToken.address,
    collateralToken: market.collateralToken.address,
    oracle: market.oracle,
    irm: market.irm,
    lltv: market.lltv
  };
}
export function getMarketParamsArray(market) {
  return [
    market.loanToken.address,
    market.collateralToken.address,
    market.oracle,
    market.irm,
    market.lltv
  ];
}
